fn append(v: Vec[Int], value: Int) -> Vec[Int] {
  v.push(value);
  return v;
}

fn double_and_return(v: Vec[Int]) -> Vec[Int] {
  var i = 0;
  while i < v.len() {
    v[i] = v[i] * 2;
    i = i + 1;
  }
  return v;
}

fn main() -> Int {
  let v = Vec[Int]();
  v.push(1);
  v.push(2);
  let v = append(v, 3);
  let v = double_and_return(v);
  var sum = 0;
  var i = 0;
  while i < v.len() {
    sum = sum + v[i];
    i = i + 1;
  }
  return sum;
}
